<script>
import Layout from "../../layouts/main";
import appConfig from "@/app.config";
import PageHeader from "@/components/page-header";

export default {
  page: {
    meta: [
      {
        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {
    Layout,
    PageHeader,
  },
  data() {
    return {
      neighborhoods: [],
      Neighborhoods: {},
      page: 1,
      limit: 20,
      tot_pages: 0,
      searchNeighborhoods: null,
      NeighborhoodsSearchMode: false,
      // appprices:[]
    };
  },
  methods: {
    addNeighborhoods() {
      var data = {
        title: "popups.addUsers",
        inputs: [
          { model: "id", type: "text", label: "id" },

          { model: "name", type: "text", label: "name" },

          { model: "branch_id", type: "text", label: "branch_id" },

          { model: "created", type: "text", label: "created" },

          { model: "updated", type: "text", label: "updated" },
        ],
        buttons: [
          {
            text: "add",
            closer: true,
            color: "primary",
            handler: (obj) => {
              this.http.post("neighborhoods", obj).then(() => {
                this.get(this.page);
              });
            },
          },
          {
            text: "Cancel",
            closer: true,
            color: "danger",
            handler: () => {
              console.log("Like Clicked");
            },
          },
        ],
      };
      this.popup.modal(data);
    },
    search() {
      this.NeighborhoodsSearchMode = true;
      this.tot_pages = 0;
      this.http
        .post("neighborhoods/search", { search: this.searchNeighborhoods })
        .then((res) => {
          this.neighborhoods = res.data;
        });
    },
    cancelappsearchMode() {
      this.searchNeighborhoods = "";
      this.NeighborhoodsSearchMode = false;
      this.get(this.page);
    },
    getNeighborhoods() {
      this.http.get("neighborhoods").then((res) => {
        this.neighborhoods = res.data;
      });
    },
    deleteNeighborhoods(app) {
      var data = {
        title: "popups. deletesms",
        template: `
          <h5>Are you sure you want to delete ?</h5> 
   
        `,
        buttons: [
          {
            text: "Delete",
            closer: true,
            color: "danger",
            handler: () => {
              console.log(app);
              this.http.delete("neighborhoods", app.id).then(() => {
                this.get(this.page);
              });
            },
          },
          {
            text: "Cancel",
            closer: true,
            color: "light",
            handler: () => {
              console.log("Like Clicked");
            },
          },
        ],
      };
      this.popup.modal(data);
    },

    get(page) {
      console.log(page);
      this.http
        .post("neighborhoods/pagination", {
          limit: this.limit,
          page: page,
        })
        .then((res) => {
          this.page = page;
          this.tot_pages = Math.ceil(res.tot / this.limit);
          this.neighborhoods = res.data;
        });
    },
  },
  created() {
    this.get(1);
    this.getNeighborhoods();
  },
};
</script>

<template>
  <Layout>
    <PageHeader title="Payment App" />
    <button
      type="button"
