          <th scope="col">Name</th>
          <th scope="col">Area Code</th>
          <th scope="col">branch_id</th>
          <th scope="col">created</th>
          <th scope="col">updated</th>
        </tr>
      </thead>
      <tbody>
        <tr
          v-for="(app, index) in neighborhoods"
          :key="app"
          class="text-center"
        >
          <td>{{ index + 1 }}</td>

          <td>
            <img v-bind:src="app.img" class="avatar-sm" />
          </td>
          <td>{{ neighborhoods.id }}</td>
          <td>{{ neighborhoods.name }}</td>
          <td>{{ neighborhoods.area_code }}</td>
          <td>{{ neighborhoods.branch_id }}</td>
          <td>{{ neighborhoods.created }}</td>
          <td>{{ neighborhoods.updated }}</td>
          <button
            type="button"
            class="btn btn-outline-light"
            style="margin-right: 1rem !important"
            data-bs-toggle="tooltip"
            data-bs-placement="top"
            title="vdio"
          >
            <i
              class="bx bxs-video font-size-24 text-danger fa-9x"
              data-bs-toggle="modal"
              data-bs-target="#video"
            ></i>
          </button>
          <td><img v-bind:src="app.icon" class="avatar-sm" /></td>
          <td>{{ app.p_lang }}</td>
          <td>{{ app.created }}</td>

          <td>
            <div class="row" text-center>
              <div class="col-3 mt-2 ms-5">
                <b-form-checkbox switch></b-form-checkbox>
              </div>
              <div class="col-3">
                <router-link
                  :to="'/app_dashboard/' + app.id"
                  type="button"
                  class="btn btn-outline-light"
                  style="margin-right: 1rem !important"
                >
                  <i
                    class="bx bxs-edit-alt font-size-24 text-success fa-9x"
                    data-bs-toggle="tooltip"
                    data-bs-placement="top"
                    title="Edit"
                  ></i>
                </router-link>
              </div>
              <div class="col-3">
                <button
                  type="button"
                  class="btn btn-light"
                  @click="deleteNeighborhoods(app)"
                >
                  <i
                    class="mdi mdi-trash-can font-size-18 text-danger fa-9x"
                  ></i>
                </button>
              </div>
            </div>
          </td>
        </tr>
      </tbody>
    </table>
    <!-- end  table -->
    <!-- Button trigger modal -->

    <!-- Modal -->
    <div
      class="modal fade"
      id="video"
      tabindex="-1"
      aria-labelledby="exampleModalLabel"
      aria-hidden="true"
    >
      <div class="modal-dialog">
        <div class="modal-content">
          <div class="modal-header">
            <h5 class="modal-title" id="exampleModalLabel">Modal video</h5>
            <button
              type="button"
              class="btn-close"
              data-bs-dismiss="modal"
              aria-label="Close"
            ></button>
          </div>
          <div class="modal-body">
            <video style="width: 470px; height: 360px" controls>
              <source src="/Rec 0008.mp4" type="video/mp4" />
              <source src="/Rec 0008.mp4" type="video/ogg" />
              <source src="/Rec 0008.mp4" type="video/webm" />
              <source src="/Rec 0008.mp4" type="video/x-flv" />
            </video>
          </div>
